#include <Wire.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_MPU6050.h>

#define JOY_HORZ_PIN 36
#define JOY_VERT_PIN 39
#define JOY_SEL_PIN  32

#define BUZZER_PIN  19

#define FLAME_PIN 4
#define GAS_PIN   34
#define PIR_PIN   27

#define GAS_THRESHOLD 2500

Adafruit_SSD1306 display(128, 64, &Wire, -1);
Adafruit_MPU6050 mpu;

struct SensorData {
  float ax, ay, az;
  float gx, gy, gz;
  bool fire;
  int gasVal;
  bool motion;
};

SensorData readings;

uint32_t pageSwitchedAt = 0;
uint8_t currentPage = 0;
const uint16_t PAGE_INTERVAL_MS = 3000; 
const uint8_t PAGE_COUNT = 2;           

uint32_t lastJoyCheck = 0;

void setup() {
  Serial.begin(115200);

  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(FLAME_PIN, INPUT);
  pinMode(PIR_PIN, INPUT);
  pinMode(JOY_SEL_PIN, INPUT_PULLUP);

  Wire.begin(); 

  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("oled didn't init, check wiring / address");
  }
  display.clearDisplay();
  display.display();

  if (!mpu.begin()) {
    Serial.println("no mpu6050 found");

  } else {
    mpu.setAccelerometerRange(MPU6050_RANGE_8_G);
    mpu.setGyroRange(MPU6050_RANGE_500_DEG);
    mpu.setFilterBandwidth(MPU6050_BAND_21_HZ);
  }
}

void readIMU() {
  sensors_event_t accel, gyro, temp;
  mpu.getEvent(&accel, &gyro, &temp);

  readings.ax = accel.acceleration.x;
  readings.ay = accel.acceleration.y;
  readings.az = accel.acceleration.z;
  readings.gx = gyro.gyro.x;
  readings.gy = gyro.gyro.y;
  readings.gz = gyro.gyro.z;
}

void readHazardSensors() {
  readings.fire = (digitalRead(FLAME_PIN) == LOW);
  readings.gasVal = analogRead(GAS_PIN);
  readings.motion = (digitalRead(PIR_PIN) == HIGH);
}

void handleJoystick() {

  if (millis() - lastJoyCheck < 300) return;

  int horz = analogRead(JOY_HORZ_PIN);



  if (horz < 1000) {
    currentPage = (currentPage + PAGE_COUNT - 1) % PAGE_COUNT;
    pageSwitchedAt = millis();
    lastJoyCheck = millis();
  } else if (horz > 3000) {
    currentPage = (currentPage + 1) % PAGE_COUNT;
    pageSwitchedAt = millis();
    lastJoyCheck = millis();
  }
}

void checkAlerts() {
  bool danger = readings.fire || readings.gasVal > GAS_THRESHOLD;

  digitalWrite(BUZZER_PIN, danger);
}

void drawMotionPage() {
  display.println("-- MOTION --");
  display.printf("ax: %.1f m/s2\n", readings.ax);
  display.printf("ay: %.1f m/s2\n", readings.ay);
  display.printf("az: %.1f m/s2\n", readings.az);

}

void drawHazardPage() {
  display.println("-- HAZARDS --");
  display.printf("flame: %s\n", readings.fire ? "FIRE!" : "clear");
  display.printf("gas:   %d\n", readings.gasVal);
  display.printf("pir:   %s\n", readings.motion ? "motion" : "none");
}

void refreshDisplay() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);

  if (currentPage == 0) {
    drawMotionPage();
  } else {
    drawHazardPage();
  }

  display.display();
}

void loop() {
  readIMU();
  readHazardSensors();
  checkAlerts();
  handleJoystick();


  if (millis() - pageSwitchedAt > PAGE_INTERVAL_MS) {
    currentPage = (currentPage + 1) % PAGE_COUNT;
    pageSwitchedAt = millis();
  }

  refreshDisplay();
  delay(50); 
}
